import{_ as e,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse(`{"title":"Export Products","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-products-export","title":"Export Products (CSV)","description":"Download the products datagrid as a CSV file — the same data the admin Catalog → Products \\"Export\\" button produces. Honours the same filters as the listing and exports EVERY matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output products.csv\\n","response":"# Binary response: a text/csv attachment is written to products.csv\\n# (Content-Type: text/csv; charset=UTF-8\\n#  Content-Disposition: attachment; filename=\\"products.csv\\"). Sample contents:\\n\\nID,Name,SKU,\\"Attribute Family\\",Price,Quantity,Status,Category,Type\\n1,\\"Coastal Breeze Men's Blue Zipper Hoodie\\",COASTALBREEZEMENSHOODIE,Default,$100.00,10000,Active,Fashion,simple\\n22,\\"Acme Drawstring Bag\\",bagistoNGRY3424234KJCKJK,Default,\\"$3,000.00\\",0,Active,,bundle\\n2705,,temporary-sku-8816cd,Default,,1,Disabled,,simple\\n"},{"id":"admin-products-export-xlsx","title":"Export Products (XLSX)","description":"Download the products datagrid as an XLSX file — the same data the admin Catalog → Products \\"Export\\" button produces. Honours the same filters as the listing and exports EVERY matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output products.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"products.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-products-export-xls","title":"Export Products (XLS)","description":"Download the products datagrid as an XLS file — the same data the admin Catalog → Products \\"Export\\" button produces. Honours the same filters as the listing and exports EVERY matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output products.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"products.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-products-export-filtered","title":"Export Products (filtered)","description":"The export honours every listing filter — pass them as query params to export exactly the rows you are viewing. Here only active products of one attribute family within a price band are exported.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products/export?format=csv&status=1&attribute_family=1&price_from=50&price_to=200\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output products.csv\\n","response":"# Only rows matching status=1 AND attribute_family=1 AND price in [50,200]\\n# are written. Filters are AND-combined (see below).\\n\\nID,Name,SKU,\\"Attribute Family\\",Price,Quantity,Status,Category,Type\\n1,\\"Coastal Breeze Men's Blue Zipper Hoodie\\",COASTALBREEZEMENSHOODIE,Default,$100.00,10000,Active,Fashion,simple\\n"},{"id":"admin-products-export-bad-format","title":"Unsupported format (422)","description":"Only format=csv is supported. Any other value returns 422.","query":"curl -i -X GET \\"https://your-domain.com/api/admin/catalog/products/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\"\\n","response":"HTTP/1.1 422 Unprocessable Content\\nContent-Type: application/json\\n\\n{\\n  \\"message\\": \\"Only the csv export format is supported.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/export.md","filePath":"api/rest-api/admin/catalog/products/export.md","lastUpdated":1787290888000}`),d={name:"api/rest-api/admin/catalog/products/export.md"};function n(s,t,c,i,p,l){return r(),o("div",null,t[0]||(t[0]=[a('<h1 id="export-products" tabindex="-1">Export Products <a class="header-anchor" href="#export-products" aria-label="Permalink to &quot;Export Products&quot;">​</a></h1><p>Downloads the products datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Catalog → Products</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON.</p><p>Unlike the <a href="/api/rest-api/admin/catalog/products.html">listing</a>, the export is <strong>not paginated</strong> — it streams <strong>every row that matches the current filters</strong>, so you can export a whole filtered catalog in one call.</p><p>Export is REST-only. The response is a file stream, which GraphQL cannot express, so there is no matching operation on the GraphQL endpoint.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/export</code></td><td>GET</td></tr></tbody></table><h2 id="request-headers" tabindex="-1">Request headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>Authorization</code></td><td><code>Bearer &lt;token&gt;</code></td></tr><tr><td><code>Accept</code></td><td><code>text/csv</code> — <strong>required</strong>. The endpoint only produces <code>text/csv</code>; sending <code>Accept: application/json</code> returns <code>406 Not Acceptable</code>.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>format</code></td><td>string</td><td>Export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>. Any other value returns <code>422</code>. Send a matching <code>Accept</code> header: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</td></tr></tbody></table><p>The export also accepts the <strong>same filters as the <a href="/api/rest-api/admin/catalog/products.html">listing</a></strong>, AND-combined (more filters = narrower result):</p><table tabindex="0"><thead><tr><th>Filter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>channel</code></td><td>string</td><td>Channel code for value resolution.</td></tr><tr><td><code>name</code></td><td>string</td><td>Partial product-name match.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Partial SKU match.</td></tr><tr><td><code>attribute_family</code></td><td>integer</td><td>Attribute-family ID.</td></tr><tr><td><code>price_from</code> / <code>price_to</code></td><td>number</td><td>Price band (inclusive). <code>price=50,200</code> is shorthand for both.</td></tr><tr><td><code>product_id</code></td><td>string</td><td>A single ID or a comma-separated list (e.g. <code>1,22,2705</code>).</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>0</code> (disabled) or <code>1</code> (active).</td></tr><tr><td><code>type</code></td><td>string</td><td><code>simple</code>, <code>virtual</code>, <code>downloadable</code>, <code>grouped</code>, <code>bundle</code>, <code>configurable</code>, <code>booking</code>.</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the nine datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Product ID.</td></tr><tr><td><code>Name</code></td><td>Product name for the resolved locale (empty for draft products with no name yet).</td></tr><tr><td><code>SKU</code></td><td>Product SKU.</td></tr><tr><td><code>Attribute Family</code></td><td>The product&#39;s attribute-family name.</td></tr><tr><td><code>Price</code></td><td>The base price, formatted (e.g. <code>$100.00</code>). Empty for composite types (<code>configurable</code> / <code>bundle</code> / <code>grouped</code> / <code>booking</code>) that carry no own price.</td></tr><tr><td><code>Quantity</code></td><td>Total stock across inventory sources.</td></tr><tr><td><code>Status</code></td><td><code>Active</code> or <code>Disabled</code>.</td></tr><tr><td><code>Category</code></td><td>The primary category name (empty when uncategorised).</td></tr><tr><td><code>Type</code></td><td>The product type.</td></tr></tbody></table><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>catalog.products</code></p>',17)]))}const m=e(d,[["render",n]]);export{h as __pageData,m as default};
